#!/usr/bin/env bash
set -euo pipefail

ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -f "$APP/index.html" ]] || APP="$ROOT"
INDEX="$APP/index.html"

[[ -f "$INDEX" ]] || {
  echo "ERROR: index.html not found. Run this from ~/workspace."
  exit 1
}

PATCH_DIR="$APP/.memeflow-patches/wallet-icon-clean-v4"
mkdir -p "$PATCH_DIR"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$PATCH_DIR/index.html.$STAMP.bak"
WORK="$PATCH_DIR/index.html.$STAMP.work"
PYTMP="$PATCH_DIR/wallet_icon_v4_$STAMP.py"

cp "$INDEX" "$BACKUP"
cp "$INDEX" "$WORK"

rollback(){
  cp "$BACKUP" "$INDEX" 2>/dev/null || true
  rm -f "$WORK" "$PYTMP"
}
trap 'echo "ERROR: WALLET ICON CLEAN V4 failed; restoring exact pre-install index.html."; rollback' ERR

printf '%s' '' | base64 -d > "$PYTMP"
python3 "$PYTMP" "$WORK"

cp "$WORK" "$INDEX"
rm -f "$WORK" "$PYTMP"

cat > "$PATCH_DIR/latest-manifest.txt" <<EOF
INDEX=$INDEX
BACKUP=$BACKUP
EOF

trap - ERR

echo
echo "OK: WALLET ICON CLEAN V4 installed cleanly."
echo "Result:"
echo "  - no visible wallet tile/frame"
echo "  - 24-25px premium line wallet glyph"
echo "  - 42-44px invisible touch target"
echo "  - neutral status dot when offline"
echo "  - green status dot when connected"
echo "  - one wallet CSS owner only"
echo
echo "Now Stop -> Run, then hard-refresh Safari."
